use crate::{catalog,model::*,rules::*,unit_support::*};
#[test]fn cq12_closed_original_identity(){let c=catalog::catalog().cards.iter().find(|c|c.id=="CQ12").expect("CQ12 original must be registered closed");assert!(!c.supported);assert_eq!((c.cost,c.color.as_str(),c.defense),(5,"红",Some(3)));assert_eq!(c.loyalty,vec!["红色","红色"]);}
fn setup()->(Game,String){let mut g=game();fund(&mut g,0,"JC042",2);field(&mut g,"JC125",0);let c=g.make_card("CQ12",0);let id=c.id.clone();g.players[0].hand.push(c);g.begin_window(Window::Prepare);(g,id)}
fn omen(id:&str,r:usize)->Action{Action{card_id:Some(id.into()),ability_id:Some(crate::cq12::OMEN.into()),region:Some(r),..Action::new("activate")}}
fn top(g:&mut Game){for _ in 0..20{if g.stack.is_empty(){return;}crate::jc029_tests::pass_top(g);}panic!("omen did not resolve")}
#[test]fn cq12_omen_real_action_restore_and_once(){let(mut g,id)=setup();assert!(g.legal_actions(0).iter().any(|a|a.action==omen(&id,0)));act(&mut g,0,omen(&id,0));assert!(g.players[0].hand.iter().any(|c|c.id==id));let r=crate::jc029_tests::envelope(&g);crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).unwrap();top(&mut g);assert_eq!(g.regions[0].cards.iter().filter(|c|c.definition=="TK008").count(),1);reject(&mut g,0,omen(&id,0));}
#[test]fn cq12_omen_rejects_empty_teammate_hidden_wrong_step_assets(){for mode in 0..5{let(mut g,id)=setup();match mode{0=>g.regions[0].cards.clear(),1=>g.regions[0].cards[0].controller=2,2=>g.regions[0].cards[0].face_down=true,3=>g.begin_window(Window::Action(0)),_=>{g.players[0].assets.pop();}}reject(&mut g,0,omen(&id,0));}}
#[test]fn cq12_omen_frozen_region_survives_occupant_departure_not_replacement(){for replace in [false,true]{let(mut g,id)=setup();act(&mut g,0,omen(&id,0));let occupant=g.regions[0].cards[0].id.clone();g.return_hand(&occupant);if replace{g.regions[0].card=g.make_card("DQJC115",0);}restore(&mut g);top(&mut g);assert_eq!(g.regions[0].cards.iter().filter(|c|c.definition=="TK008").count(),usize::from(!replace));}}
#[test]fn cq12_omen_corrupt_game_and_room_rejected(){let(mut g,id)=setup();act(&mut g,0,omen(&id,0));for n in 0..7{let mut x=g.clone();let f=x.stack.last_mut().unwrap().frame.as_mut().unwrap();match n{0=>f.already_paid.clear(),1=>f.steps.clear(),2=>f.source.card.definition="JC125".into(),3=>f.chosen_region=Some(1),4=>if let Op::CQ12Omen{witness:Some(w)}=&mut f.steps[0].op{w.red_assets[1]=w.red_assets[0].clone()},5=>x.turn_ability_usage.clear(),_=>{let i=x.stack.last().unwrap().clone();x.stack.push(i)}}assert!(Game::from_persisted(&serde_json::to_string(&x).unwrap()).is_err(),"mutation {n}");let mut r=crate::jc029_tests::envelope(&g);r.game=x;assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}}
#[test]fn cq12_sacrifice_discount_deploy_and_paid_reveal(){for reveal in [false,true]{let mut g=game();fund(&mut g,0,"JC042",2);let mut ids=vec![];for _ in 0..3{ids.push(field(&mut g,"JC125",0));}let mut c=g.make_card("CQ12",0);let id=c.id.clone();if reveal{c.face_down=true;g.regions[0].cards.push(c);}else{g.players[0].hand.push(c);}let a=Action{card_id:Some(id),region:if reveal{None}else{Some(0)},..Action::new(if reveal{"reveal"}else{"deploy"})};act(&mut g,0,a);assert_eq!(g.pending.as_ref().unwrap().choice.kind,"cq12-sacrifice");choose(&mut g,ids);assert_eq!(g.players[0].graveyard.len(),3);top(&mut g);assert!(g.regions[0].cards.iter().any(|c|c.definition=="CQ12"&&!c.face_down));restore(&mut g);}}
#[test]fn cq12_sacrifice_rejects_duplicate_enemy_and_underafford(){let mut g=game();fund(&mut g,0,"JC042",2);let v=field(&mut g,"JC125",0);let e=field(&mut g,"JC125",1);let c=g.make_card("CQ12",0);let id=c.id.clone();g.players[0].hand.push(c);for ids in [vec![v.clone();3],vec![e],vec![v]]{reject(&mut g,0,Action{card_id:Some(id.clone()),region:Some(0),cost_selected:Some(ids),..Action::new("deploy")});}}
#[test]fn cq12_pending_sacrifice_original_and_frame_receipt_restore(){let mut g=game();fund(&mut g,0,"JC042",5);let v=field(&mut g,"JC125",0);let c=g.make_card("CQ12",0);let id=c.id.clone();g.players[0].hand.push(c);act(&mut g,0,Action{card_id:Some(id),region:Some(0),..Action::new("deploy")});let mut x=g.clone();x.pending.as_mut().unwrap().choice.max=Some(99);assert!(Game::from_persisted(&serde_json::to_string(&x).unwrap()).is_err());choose(&mut g,vec![v]);let mut x=g.clone();x.stack.last_mut().unwrap().frame.as_mut().unwrap().already_paid.pop();assert!(Game::from_persisted(&serde_json::to_string(&x).unwrap()).is_err());top(&mut g);}
#[test]fn cq12_red_asset_if_is_resolution_condition_not_extra_cost(){for lose in [false,true]{let(mut g,id)=setup();if !lose{g.players[0].assets.clear();fund(&mut g,0,"JC125",2);}act(&mut g,0,omen(&id,0));if lose{g.players[0].assets.pop();}restore(&mut g);top(&mut g);assert!(!g.regions[0].cards.iter().any(|c|c.definition=="TK008"));}}
#[test]fn cq12_sacrificed_generated_tokens_vanish_in_actual_deploy(){let mut g=game();fund(&mut g,0,"JC042",2);let mut ids=vec![];for _ in 0..3{let c=g.make_generated(crate::generated::GeneratedKind::Cultist,0).unwrap();ids.push(c.id.clone());g.regions[0].cards.push(c);}let c=g.make_card("CQ12",0);let id=c.id.clone();g.players[0].hand.push(c);act(&mut g,0,Action{card_id:Some(id),region:Some(0),..Action::new("deploy")});assert_eq!(g.pending.as_ref().unwrap().choice.min,Some(3));choose(&mut g,ids);top(&mut g);assert!(!g.batch3_physical_cards().any(|c|c.definition=="TK008"));assert!(g.players[0].graveyard.is_empty());}
